//! In-memory record of every request that passed through the gateway.

use std::{
    collections::VecDeque,
    sync::{Arc, Mutex},
};

use serde::Serialize;

/// How many finished requests we keep in memory.
const MAX_RECORDS: usize = 1000;

/// What we know about one finished request.
#[derive(Clone, Debug, Serialize)]
pub struct RequestRecord {
    pub id: u64,
    pub stream: bool,
    /// Prompt tokens, if the upstream server reported them.
    pub prompt_tokens: Option<u64>,
    /// Tokens generated by the model.
    pub completion_tokens: u64,
    /// Time to first token (streaming only): roughly the prefill phase.
    pub ttft_ms: Option<f64>,
    /// Total time from request received to response finished.
    pub total_ms: f64,
    /// Decode throughput: tokens after the first, divided by time after the first.
    pub decode_tokens_per_s: Option<f64>,
    /// False if the client disconnected before the response finished.
    pub completed: bool,
}

#[derive(Clone, Default)]
pub struct Stats {
    records: Arc<Mutex<VecDeque<RequestRecord>>>,
}

#[derive(Serialize)]
pub struct Summary {
    pub requests: usize,
    pub total_completion_tokens: u64,
    pub avg_ttft_ms: Option<f64>,
    pub avg_total_ms: Option<f64>,
    pub recent: Vec<RequestRecord>,
}

impl Stats {
    pub fn push(&self, record: RequestRecord) {
        println!(
            "req #{:<4} stream={:<5} tokens={:<5} ttft={:>8} total={:>8.1}ms decode={}",
            record.id,
            record.stream,
            record.completion_tokens,
            record.ttft_ms.map(|t| format!("{t:.1}ms")).unwrap_or("-".into()),
            record.total_ms,
            record
                .decode_tokens_per_s
                .map(|t| format!("{t:.1} tok/s"))
                .unwrap_or("-".into()),
        );
        let mut records = self.records.lock().unwrap();
        if records.len() == MAX_RECORDS {
            records.pop_front();
        }
        records.push_back(record);
    }

    pub fn summary(&self) -> Summary {
        let records = self.records.lock().unwrap();
        let avg = |values: Vec<f64>| {
            (!values.is_empty()).then(|| values.iter().sum::<f64>() / values.len() as f64)
        };
        Summary {
            requests: records.len(),
            total_completion_tokens: records.iter().map(|r| r.completion_tokens).sum(),
            avg_ttft_ms: avg(records.iter().filter_map(|r| r.ttft_ms).collect()),
            avg_total_ms: avg(records.iter().map(|r| r.total_ms).collect()),
            recent: records.iter().rev().take(20).cloned().collect(),
        }
    }
}
